CREATE OR REPLACE FUNCTION public.cancel_trip_activity_v1(p_operation_id uuid, p_trip_id uuid, p_vineyard_id uuid, p_application text, p_client_baseline jsonb DEFAULT '{}'::jsonb, p_compliance_facts jsonb DEFAULT NULL::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_uid uuid := auth.uid(); v_role text; v_trip public.trips;
  v_existing public.trip_activity_cancellation_receipts; v_receipt public.trip_activity_cancellation_receipts;
  v_spray uuid[]; v_archive uuid; n_actuals integer := 0; n_spray integer := 0; n_cost integer := 0;
begin
  if v_uid is null then raise exception 'TRIP_CANCEL_AUTH_REQUIRED' using errcode = '42501'; end if;
  if p_operation_id is null or p_trip_id is null or p_vineyard_id is null then raise exception 'TRIP_CANCEL_INVALID_IDENTITY' using errcode = '22023'; end if;
  if p_application is null or p_application not in ('not_applied', 'applied') then raise exception 'TRIP_CANCEL_CLASSIFICATION_REQUIRED' using errcode = '22023'; end if;
  if p_client_baseline is null or jsonb_typeof(p_client_baseline) <> 'object' then raise exception 'TRIP_CANCEL_INVALID_BASELINE' using errcode = '22023'; end if;
  v_role := public.vineyard_role(p_vineyard_id);
  if v_role is null or v_role not in ('owner', 'manager', 'supervisor') then raise exception 'TRIP_CANCEL_FORBIDDEN' using errcode = '42501'; end if;
  select * into v_existing from public.trip_activity_cancellation_receipts where operation_id = p_operation_id;
  if found then
    if v_existing.trip_id <> p_trip_id or v_existing.vineyard_id <> p_vineyard_id or v_existing.application_classification <> p_application then raise exception 'TRIP_CANCEL_OPERATION_CONFLICT' using errcode = '23505'; end if;
    return public.trip_cancellation_receipt_json_v1(v_existing) || jsonb_build_object('replayed', true);
  end if;
  if exists (select 1 from public.trip_activity_cancellation_receipts where trip_id = p_trip_id) then raise exception 'TRIP_CANCEL_ALREADY_CANCELLED_OTHER_OPERATION' using errcode = '23505'; end if;
  select * into v_trip from public.trips where id = p_trip_id for update;
  if not found or v_trip.vineyard_id <> p_vineyard_id then raise exception 'TRIP_CANCEL_TRIP_NOT_FOUND' using errcode = 'P0002'; end if;
  if v_trip.deleted_at is not null then raise exception 'TRIP_CANCEL_TRIP_ALREADY_DELETED' using errcode = '55000'; end if;
  if v_trip.end_time is not null then raise exception 'TRIP_CANCEL_TRIP_COMPLETED' using errcode = '55000'; end if;
  if coalesce(v_trip.entry_source, '') = 'manual' then raise exception 'TRIP_CANCEL_MANUAL_ENTRY_UNSUPPORTED' using errcode = '0A000'; end if;
  select coalesce(array_agg(id order by id), '{}') into v_spray from public.spray_records where trip_id = p_trip_id and vineyard_id = p_vineyard_id and deleted_at is null;
  if exists (select 1 from public.spray_records where id = any (v_spray) and coalesce(entry_source, '') = 'manual') then raise exception 'TRIP_CANCEL_MANUAL_ENTRY_UNSUPPORTED' using errcode = '0A000'; end if;
  if p_application = 'not_applied' then
    if exists (select 1 from public.spray_tank_actuals where trip_id = p_trip_id and deleted_at is null) then raise exception 'TRIP_CANCEL_SERVER_ACTUALS_REQUIRE_APPLIED_REVIEW' using errcode = '55000'; end if;
  else
    if p_compliance_facts is null or jsonb_typeof(p_compliance_facts) <> 'object' or p_compliance_facts = '{}'::jsonb then raise exception 'TRIP_CANCEL_COMPLIANCE_FACTS_REQUIRED' using errcode = '22023'; end if;
    insert into public.trip_compliance_archive (operation_id, trip_id, vineyard_id, source, facts, retain_until, created_by)
    values (p_operation_id, p_trip_id, p_vineyard_id, 'applied_trip_cancellation', jsonb_build_object('client_application_facts', p_compliance_facts, 'server_trip', to_jsonb(v_trip), 'server_spray_records', coalesce((select jsonb_agg(to_jsonb(s)) from public.spray_records s where s.id = any (v_spray)), '[]'::jsonb), 'server_tank_actuals', coalesce((select jsonb_agg(to_jsonb(a)) from public.spray_tank_actuals a where a.trip_id = p_trip_id and a.deleted_at is null), '[]'::jsonb), 'actor_user_id', v_uid, 'actor_role', v_role, 'archived_at', now()), (now() + interval '3 years')::date, v_uid)
    returning id into v_archive;
  end if;
  update public.spray_tank_actuals set deleted_at = now() where trip_id = p_trip_id and deleted_at is null;
  get diagnostics n_actuals = row_count;
  update public.trip_cost_allocations set deleted_at = now(), updated_by = v_uid where trip_id = p_trip_id and deleted_at is null;
  get diagnostics n_cost = row_count;
  update public.spray_records set deleted_at = now(), updated_by = v_uid where id = any (v_spray) and deleted_at is null;
  get diagnostics n_spray = row_count;
  update public.trips set deleted_at = now(), updated_by = v_uid where id = p_trip_id;
  insert into public.trip_activity_cancellation_receipts (operation_id, trip_id, vineyard_id, actor_user_id, actor_role, application_classification, compliance_archive_id, spray_record_ids, removed_counts, client_baseline)
  values (p_operation_id, p_trip_id, p_vineyard_id, v_uid, v_role, p_application, v_archive, v_spray, jsonb_build_object('trip', 1, 'spray_records', n_spray, 'spray_tank_actuals', n_actuals, 'trip_cost_allocations', n_cost), p_client_baseline)
  returning * into v_receipt;
  return public.trip_cancellation_receipt_json_v1(v_receipt) || jsonb_build_object('replayed', false);
end $function$

CREATE OR REPLACE FUNCTION public.complete_spray_record(p_spray_record_id uuid, p_allow_unlinked boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_actor uuid := auth.uid();
  v_spray public.spray_records%rowtype;
  v_trip public.trips%rowtype;
  v_end_time timestamptz;
  v_source text;
begin
  if v_actor is null then
    raise exception 'AUTH_REQUIRED' using errcode = '42501',
      detail = 'Authentication required.';
  end if;

  -- Lock order is always Spray, then its current linked Trip (if present).
  -- Do not filter away deleted rows: distinguish unavailable canonical states.
  select r.* into v_spray
  from public.spray_records r where r.id = p_spray_record_id for update;
  if not found then
    raise exception 'SPRAY_NOT_FOUND' using errcode = 'P0002';
  end if;
  -- Role check precedes state disclosure, including an idempotent result.
  if not public.has_vineyard_role(
    v_spray.vineyard_id, array['owner', 'manager', 'supervisor', 'operator']
  ) then
    raise exception 'SPRAY_EDIT_FORBIDDEN' using errcode = '42501';
  end if;
  if v_spray.deleted_at is not null then
    raise exception 'SPRAY_DELETED' using errcode = '55000';
  end if;
  if v_spray.is_template is distinct from false then
    raise exception 'SPRAY_TEMPLATE' using errcode = '55000',
      detail = 'Program Steps cannot be completed as operational sprays.';
  end if;
  if v_spray.entry_source = 'manual' or v_spray.manual_entry_id is not null then
    raise exception 'MANUAL_SPRAY_WORKFLOW_REQUIRED' using errcode = '42501',
      detail = 'Manual spray records must be managed through the manual spray workflow.';
  end if;

  if v_spray.trip_id is not null then
    select t.* into v_trip
    from public.trips t where t.id = v_spray.trip_id for update;
  end if;

  -- Explicit completion wins. No UPDATE, audit bump or trigger on a retry.
  -- An already-completed valid Spray remains idempotent even if its historical
  -- Trip is later unavailable/active; no new completion is being authorised.
  if v_spray.end_time is not null then
    v_source := 'existing';
  else
    if v_spray.trip_id is not null then
      if v_trip.id is null or v_trip.deleted_at is not null then
        raise exception 'LINKED_TRIP_UNAVAILABLE' using errcode = '55000';
      end if;
      if v_trip.vineyard_id is distinct from v_spray.vineyard_id then
        raise exception 'LINKED_TRIP_VINEYARD_MISMATCH' using errcode = '55000';
      end if;
      if v_trip.is_active is true then
        raise exception 'ACTIVE_TRIP' using errcode = '55000',
          detail = 'This spray still has an active Trip. End the Trip to complete the spray.';
      end if;
      if v_trip.is_active is distinct from false or v_trip.end_time is null then
        raise exception 'LINKED_TRIP_NOT_ENDED' using errcode = '55000';
      end if;
      -- Reject contradictory ended states, without repairing historical data.
      -- A missing historical start is not itself grounds to invent a start.
      if v_trip.entry_source = 'manual' or v_trip.manual_entry_id is not null
         or not isfinite(v_trip.end_time)
         or (v_trip.start_time is not null and v_trip.end_time < v_trip.start_time) then
        raise exception 'LINKED_TRIP_INCONSISTENT' using errcode = '55000';
      end if;
      v_end_time := v_trip.end_time;
      v_source := 'trip_end';
    else
      -- NULL is not affirmative confirmation. A broken trip_id never reaches here.
      if p_allow_unlinked is distinct from true then
        raise exception 'UNLINKED_CONFIRMATION_REQUIRED' using errcode = '55000',
          detail = 'No linked Trip is available. Confirm marking this spray complete now.';
      end if;
      v_end_time := now();
      v_source := 'server_now';
    end if;

    -- Same explicit audit/version convention as the existing Spray RPCs (232).
    -- updated_at is owned by spray_records_set_updated_at (007 / set_updated_at).
    -- Keep all provenance, planning/application fields and Trips untouched.
    update public.spray_records r
    set end_time = v_end_time,
        updated_by = v_actor,
        client_updated_at = now(),
        sync_version = r.sync_version + 1
    where r.id = v_spray.id
    returning r.* into v_spray;
    if not found or v_spray.end_time is distinct from v_end_time then
      raise exception 'SPRAY_COMPLETION_NOT_APPLIED' using errcode = '55000';
    end if;
  end if;

  return jsonb_build_object(
    'sprayRecordId', v_spray.id,
    'endTime', v_spray.end_time,
    'completionSource', v_source,
    'serverConfirmed', true,
    'updatedAt', v_spray.updated_at,
    'updatedBy', v_spray.updated_by,
    'clientUpdatedAt', v_spray.client_updated_at,
    'syncVersion', v_spray.sync_version
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.correct_spray_tank_actual_v1(p_operation_id uuid, p_actual_id uuid, p_trip_id uuid, p_spray_record_id uuid, p_tank_session_id text, p_tank_number integer, p_expected_version bigint, p_water_volume_l double precision, p_chemicals jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare t public.trips; r public.spray_records; a public.spray_tank_actuals; v_tank jsonb;
  old_water double precision; old_chems jsonb; new_version bigint; actor_name text; now_at timestamptz := clock_timestamp();
  old_c jsonb; new_c jsonb; chem_id uuid; kind text;
begin
  if auth.uid() is null then raise exception 'Authentication required' using errcode='42501'; end if;
  if p_operation_id is null or p_actual_id is null or p_expected_version is null or p_expected_version < 0 then raise exception 'Invalid correction request' using errcode='22023'; end if;
  select * into t from public.trips where id=p_trip_id and deleted_at is null for update;
  if t.id is null then raise exception 'Trip not found' using errcode='P0002'; end if;
  if not public.has_vineyard_role(t.vineyard_id,array['owner','manager','supervisor']) then raise exception 'Correction access required' using errcode='42501'; end if;
  select * into r from public.spray_records where id=p_spray_record_id and trip_id=t.id and vineyard_id=t.vineyard_id and not is_template and deleted_at is null;
  if r.id is null then raise exception 'Spray record does not match trip' using errcode='22023'; end if;
  select value into v_tank from jsonb_array_elements(coalesce(r.tanks,'[]'::jsonb))
    where coalesce((value->>'tankNumber')::integer,(value->>'tank_number')::integer)=p_tank_number limit 1;
  if v_tank is null then raise exception 'Tank is not in frozen spray plan' using errcode='22023'; end if;
  if not exists(select 1 from jsonb_array_elements(coalesce(t.tank_sessions,'[]'::jsonb)) s
    where coalesce(s->>'id',s->>'tank_session_id')=btrim(p_tank_session_id)
      and coalesce((s->>'tankNumber')::integer,(s->>'tank_number')::integer)=p_tank_number)
  then raise exception 'Tank session does not match trip tank' using errcode='22023'; end if;
  if p_water_volume_l is not null and (p_water_volume_l < 0 or p_water_volume_l<>p_water_volume_l or p_water_volume_l in ('Infinity'::double precision,'-Infinity'::double precision)) then raise exception 'Invalid actual water' using errcode='22023'; end if;
  if not public.validate_spray_tank_actual_chemicals_v1(p_chemicals,v_tank,t.vineyard_id) then raise exception 'Invalid actual chemicals' using errcode='22023'; end if;
  select coalesce(nullif(btrim(p.full_name),''),nullif(btrim(p.email),''),'VineTrack user') into actor_name from public.profiles p where p.id=auth.uid();
  actor_name := coalesce(actor_name,'VineTrack user');

  select * into a from public.spray_tank_actuals where trip_id=t.id and tank_session_id=btrim(p_tank_session_id) for update;
  if exists(select 1 from public.spray_tank_actual_amendments where operation_id=p_operation_id and trip_id=t.id and spray_tank_actual_id=p_actual_id) then
    return jsonb_build_object('actual',to_jsonb(a),'amendments',public.spray_actual_amendments_v1(t.id));
  elsif exists(select 1 from public.spray_tank_actual_amendments where operation_id=p_operation_id) then
    raise exception 'Operation ID already belongs to another correction' using errcode='22023';
  end if;
  if a.id is null then
    if p_expected_version<>0 then raise exception 'Actual usage version conflict' using errcode='40001'; end if;
    old_water:=null; old_chems:='[]'::jsonb; new_version:=1;
    insert into public.spray_tank_actuals(id,vineyard_id,spray_record_id,trip_id,tank_session_id,tank_number,water_volume_l,chemicals,confirmed_at,confirmed_by,created_by,updated_by,client_updated_at,correction_version,last_corrected_at)
    values(p_actual_id,t.vineyard_id,r.id,t.id,btrim(p_tank_session_id),p_tank_number,p_water_volume_l,p_chemicals,now_at,auth.uid(),auth.uid(),auth.uid(),now_at,new_version,now_at) returning * into a;
  else
    if a.id<>p_actual_id or a.spray_record_id<>r.id or a.tank_number<>p_tank_number then raise exception 'Actual usage identity mismatch' using errcode='22023'; end if;
    if a.correction_version<>p_expected_version then raise exception 'Actual usage version conflict' using errcode='40001'; end if;
    old_water:=a.water_volume_l; old_chems:=a.chemicals;
    if old_water is not distinct from p_water_volume_l and old_chems=p_chemicals then
      return jsonb_build_object('actual',to_jsonb(a),'amendments',public.spray_actual_amendments_v1(t.id));
    end if;
    new_version:=a.correction_version+1;
    update public.spray_tank_actuals set water_volume_l=p_water_volume_l,chemicals=p_chemicals,
      updated_by=auth.uid(),client_updated_at=now_at,correction_version=new_version,last_corrected_at=now_at
      where id=a.id returning * into a;
  end if;

  if old_water is distinct from p_water_volume_l then
    insert into public.spray_tank_actual_amendments(operation_id,vineyard_id,trip_id,spray_record_id,spray_tank_actual_id,tank_number,field_name,change_kind,previous_value,new_value,previous_unit,new_unit,revision,edited_by,editor_name,edited_at)
    values(p_operation_id,t.vineyard_id,t.id,r.id,a.id,p_tank_number,'actualWaterLitres',
      case when old_water is null and p_water_volume_l is not null then 'initialEntry' when p_water_volume_l is null then 'cleared' when p_water_volume_l=0 then 'explicitZero' else 'correction' end,
      case when old_water is null then null else to_jsonb(old_water) end,case when p_water_volume_l is null then null else to_jsonb(p_water_volume_l) end,'L','L',new_version,auth.uid(),actor_name,now_at);
  end if;
  for chem_id in select distinct id from (
    select (x->>'id')::uuid id from jsonb_array_elements(old_chems) x union
    select (x->>'id')::uuid id from jsonb_array_elements(p_chemicals) x
  ) q loop
    select value into old_c from jsonb_array_elements(old_chems) where (value->>'id')::uuid=chem_id;
    select value into new_c from jsonb_array_elements(p_chemicals) where (value->>'id')::uuid=chem_id;
    if old_c is distinct from new_c then
      kind:=case when new_c is null then 'removed' when old_c is null and coalesce(new_c->>'usageKind','additional')='substitution' then 'substitution'
        when old_c is null then 'addition' when (new_c->>'actualAmountBase')::double precision=0 then 'explicitZero' else 'correction' end;
      insert into public.spray_tank_actual_amendments(operation_id,vineyard_id,trip_id,spray_record_id,spray_tank_actual_id,tank_number,chemical_actual_id,planned_chemical_id,saved_chemical_id,field_name,change_kind,previous_value,new_value,previous_unit,new_unit,revision,edited_by,editor_name,edited_at)
      values(p_operation_id,t.vineyard_id,t.id,r.id,a.id,p_tank_number,chem_id,
        coalesce(nullif(new_c->>'plannedChemicalId',''),nullif(old_c->>'plannedChemicalId',''))::uuid,
        coalesce(nullif(new_c->>'savedChemicalId',''),nullif(old_c->>'savedChemicalId',''))::uuid,
        'actualChemical',kind,old_c,new_c,old_c->>'unit',new_c->>'unit',new_version,auth.uid(),actor_name,now_at);
    end if;
    old_c:=null; new_c:=null;
  end loop;
  return jsonb_build_object('actual',to_jsonb(a),'amendments',public.spray_actual_amendments_v1(t.id));
end $function$

CREATE OR REPLACE FUNCTION public.reconcile_deleted_trip_activity_v1(p_operation_id uuid, p_trip_id uuid, p_vineyard_id uuid, p_application text, p_attestation text, p_client_evidence jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
    v_uid uuid := auth.uid();
    v_role text;
    v_trip public.trips;
    v_existing public.trip_activity_cancellation_receipts;
    v_receipt public.trip_activity_cancellation_receipts;
    v_sprays uuid[];
    v_archive uuid;
    n_actuals integer := 0;
    n_spray integer := 0;
    n_cost integer := 0;
    v_facts jsonb;
begin
    if v_uid is null then
        raise exception 'TRIP_REVIEW_AUTH_REQUIRED' using errcode='42501';
    end if;
    if p_operation_id is null or p_trip_id is null or p_vineyard_id is null then
        raise exception 'TRIP_REVIEW_INVALID_IDENTITY' using errcode='22023';
    end if;
    if p_application is null or p_application not in ('not_applied','applied') then
        raise exception 'TRIP_REVIEW_APPLICATION_REQUIRED' using errcode='22023';
    end if;
    if p_attestation is null or length(btrim(p_attestation)) < 12
       or length(btrim(p_attestation)) > 500 then
        raise exception 'TRIP_REVIEW_EVIDENCE_NOTE_REQUIRED' using errcode='22023';
    end if;
    if p_client_evidence is null or jsonb_typeof(p_client_evidence) <> 'object'
       or octet_length(p_client_evidence::text) > 1048576 then
        raise exception 'TRIP_REVIEW_INVALID_CLIENT_EVIDENCE' using errcode='22023';
    end if;
    v_role := public.vineyard_role(p_vineyard_id);
    if v_role is null or v_role not in ('owner','manager') then
        raise exception 'TRIP_REVIEW_FORBIDDEN' using errcode='42501';
    end if;

    -- Serialize review with any other cancellation of the exact Trip.
    select * into v_trip from public.trips
      where id=p_trip_id and vineyard_id=p_vineyard_id for update;
    if not found then
        raise exception 'TRIP_REVIEW_ORIGINAL_NOT_FOUND' using errcode='P0002';
    end if;
    if v_trip.deleted_at is null then
        raise exception 'TRIP_REVIEW_NOT_DELETED' using errcode='55000';
    end if;

    select * into v_existing from public.trip_activity_cancellation_receipts
      where trip_id=p_trip_id for update;
    if found then
        if v_existing.operation_id <> p_operation_id
           or v_existing.vineyard_id <> p_vineyard_id
           or v_existing.application_classification <> p_application then
            raise exception 'TRIP_REVIEW_RECEIPT_OPERATION_CONFLICT' using errcode='23505';
        end if;
        return public.trip_cancellation_receipt_json_v1(v_existing)
            || jsonb_build_object('replayed',true,'reviewed_legacy_tombstone',true);
    end if;
    if exists (
        select 1 from public.trip_activity_cancellation_receipts
        where operation_id=p_operation_id and trip_id<>p_trip_id
    ) then
        raise exception 'TRIP_REVIEW_OPERATION_ID_CONFLICT' using errcode='23505';
    end if;

    if p_application='not_applied' and (
       exists (select 1 from public.spray_tank_actuals
               where trip_id=p_trip_id and deleted_at is null)
       or jsonb_array_length(
            case when jsonb_typeof(p_client_evidence->'tanks')='array'
                 then p_client_evidence->'tanks' else '[]'::jsonb end
          ) > 0
    ) and coalesce(
        p_client_evidence->>'confirmed_recorded_actuals_not_applied',
        'false') <> 'true' then
        raise exception 'TRIP_REVIEW_RECORDED_ACTUALS_NEED_APPLIED_REVIEW' using errcode='55000';
    end if;

    select coalesce(array_agg(id order by id),'{}') into v_sprays
      from public.spray_records where trip_id=p_trip_id and vineyard_id=p_vineyard_id
        and deleted_at is null;

    -- Compliance: retain every server-side original even if the handset never
    -- uploaded its final Actual Use. The reviewed device evidence is included
    -- verbatim, with provenance, without guessing missing fields.
    v_facts := jsonb_build_object(
        'contract','vinetrack.guided-deleted-trip-reconciliation-v1',
        'original_trip',to_jsonb(v_trip),
        'original_sprays',coalesce(
          (select jsonb_agg(to_jsonb(s)) from public.spray_records s
           where s.trip_id=p_trip_id and s.vineyard_id=p_vineyard_id), '[]'::jsonb),
        'original_tank_actuals',coalesce(
          (select jsonb_agg(to_jsonb(a)) from public.spray_tank_actuals a
           where a.trip_id=p_trip_id), '[]'::jsonb),
        'original_cost_allocations',coalesce(
          (select jsonb_agg(to_jsonb(c)) from public.trip_cost_allocations c
           where c.trip_id=p_trip_id), '[]'::jsonb),
        'operator_attestation',btrim(p_attestation),
        'application_classification',p_application,
        'client_original_evidence',p_client_evidence,
        'actor_user_id',v_uid,
        'actor_role',v_role,
        'legacy_server_deleted_at',v_trip.deleted_at,
        'reviewed_at',clock_timestamp()
    );
    insert into public.trip_compliance_archive (
        operation_id, trip_id, vineyard_id, source, facts, retain_until, created_by
    ) values (
        p_operation_id,p_trip_id,p_vineyard_id,'reviewed_legacy_trip_deletion',
        v_facts,(current_date + interval '3 years')::date,v_uid
    ) returning id into v_archive;

    update public.spray_tank_actuals set deleted_at=clock_timestamp(),
        updated_by=v_uid where trip_id=p_trip_id and deleted_at is null;
    get diagnostics n_actuals=row_count;

    update public.trip_cost_allocations set deleted_at=clock_timestamp(),
        updated_by=v_uid where trip_id=p_trip_id and deleted_at is null;
    get diagnostics n_cost=row_count;

    update public.spray_records set deleted_at=clock_timestamp(),
        updated_by=v_uid where id=any(v_sprays) and deleted_at is null;
    get diagnostics n_spray=row_count;

    insert into public.trip_activity_cancellation_receipts (
        operation_id,trip_id,vineyard_id,actor_user_id,actor_role,
        application_classification,compliance_archive_id,spray_record_ids,
        removed_counts,client_baseline
    ) values (
        p_operation_id,p_trip_id,p_vineyard_id,v_uid,v_role,p_application,
        v_archive,v_sprays,
        jsonb_build_object('trip',0,'spray_records',n_spray,
                           'spray_tank_actuals',n_actuals,
                           'trip_cost_allocations',n_cost),
        jsonb_build_object('legacy_tombstone_reviewed',true,
                           'original_deleted_at',v_trip.deleted_at,
                           'client_evidence_present',p_client_evidence<>'{}'::jsonb)
    ) returning * into v_receipt;

    return public.trip_cancellation_receipt_json_v1(v_receipt)
        || jsonb_build_object('replayed',false,'reviewed_legacy_tombstone',true);
end
$function$

CREATE OR REPLACE FUNCTION public.spray_tank_actuals_before_write()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_trip public.trips; v_record public.spray_records;
begin
  select * into v_trip from public.trips where id=new.trip_id and deleted_at is null;
  select * into v_record from public.spray_records where id=new.spray_record_id and deleted_at is null and is_template=false;
  if v_trip.id is null then raise exception 'Trip not found'; end if;
  if v_record.id is null then raise exception 'Spray record not found'; end if;
  if new.vineyard_id<>v_trip.vineyard_id or new.vineyard_id<>v_record.vineyard_id or v_record.trip_id is distinct from new.trip_id then
    raise exception 'Vineyard, trip and spray record do not match';
  end if;
  if v_record.entry_source='manual' then
    if v_trip.entry_source<>'manual' or v_trip.manual_entry_id is distinct from v_record.manual_entry_id then
      raise exception 'Manual application provenance does not match' using errcode='23514';
    end if;
    if coalesce(current_setting('vinetrack.manual_spray_rpc',true),'')<>'on' or not public.has_vineyard_role(new.vineyard_id,array['owner','manager','supervisor']) then
      raise exception 'Manual spray coordinated access required' using errcode='42501';
    end if;
    if not (tg_op='UPDATE' and old.deleted_at is null and new.deleted_at is not null) and not exists (
      select 1 from jsonb_array_elements(coalesce(v_record.tanks,'[]'::jsonb)) tank
      where coalesce(tank->>'id',tank->>'tankSessionId')=new.tank_session_id
        and coalesce((tank->>'tankNumber')::integer,(tank->>'tank_number')::integer)=new.tank_number
    ) then raise exception 'Manual tank identity does not belong to spray'; end if;
  elsif not exists (
    select 1 from jsonb_array_elements(coalesce(v_trip.tank_sessions,'[]'::jsonb)) session
    where coalesce(session->>'id',session->>'tank_session_id')=new.tank_session_id
      and coalesce((session->>'tank_number')::integer,(session->>'tankNumber')::integer)=new.tank_number
  ) then raise exception 'Tank session does not belong to trip'; end if;
  new.updated_by:=auth.uid();
  if tg_op='INSERT' then
    new.created_by:=coalesce(new.created_by,auth.uid()); new.confirmed_by:=auth.uid();
  else
    new.id:=old.id; new.created_at:=old.created_at; new.created_by:=old.created_by;
    new.confirmed_by:=old.confirmed_by; new.sync_version:=old.sync_version+1;
  end if;
  return new;
end $function$
